sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;

    // Validate required fields (only customer-legitimate inputs)
    if (!body.case_id && !body.case_number) {
        response.setStatus(400);
        response.setBody({ success: false, error: 'Either case_id or case_number is required' });
        return;
    }
    if (!body.amount_requested && body.amount_requested !== 0) {
        response.setStatus(400);
        response.setBody({ success: false, error: 'amount_requested is required' });
        return;
    }
    if (!body.request_type) {
        response.setStatus(400);
        response.setBody({ success: false, error: 'request_type is required (refund, replacement, credit)' });
        return;
    }

    // Resolve the case
    var caseGr = new GlideRecord('sn_customerservice_case');
    var caseFound = false;
    if (body.case_id) {
        caseFound = caseGr.get(body.case_id);
    } else if (body.case_number) {
        caseGr.addQuery('number', body.case_number);
        caseGr.query();
        caseFound = caseGr.next();
    }

    if (!caseFound) {
        response.setStatus(404);
        response.setBody({ success: false, error: 'Case not found' });
        return;
    }

    var amountRequested = parseFloat(body.amount_requested);
    var AUTO_APPROVE_THRESHOLD = 500;

    // ===== SECURITY: NEVER trust client input for decision, fraud, or notes =====
    // These are computed server-side only. Any values sent by the client are IGNORED.
    // Fraud detection is done by checking the case's existing fraud_review_required flag
    // and the FraudDetectionEngine business rule (fires after insert on refund_request).

    // Check if the linked case already has a fraud flag from prior triage
    var caseFraudFlagged = caseGr.getValue('x_2145749_qc_fraud_review_required') === '1' ||
                           caseGr.getValue('x_2145749_qc_fraud_review_required') === 'true';

    // Simple fraud heuristics the server applies (supplement to FraudDetectionEngine):
    // - If the case was already flagged for fraud review
    // - If amount exceeds 3x the recorded order value (potential inflation)
    var orderValue = parseFloat(caseGr.getValue('x_2145749_qc_order_value')) || 0;
    var suspiciousAmount = (orderValue > 0 && amountRequested > orderValue * 3);

    var fraudFlagged = caseFraudFlagged || suspiciousAmount;

    // Determine decision synchronously — server logic only, never from client
    var decision = '';
    var decisionNotes = '';
    var amountApproved = 0;

    if (!fraudFlagged && amountRequested <= AUTO_APPROVE_THRESHOLD) {
        decision = 'auto_approved';
        decisionNotes = 'Auto-approved: amount \u20b9' + amountRequested + ' within threshold (\u20b9' + AUTO_APPROVE_THRESHOLD + '), no fraud indicators.';
        amountApproved = amountRequested;
    } else {
        decision = 'auto_escalated';
        var reasons = [];
        if (amountRequested > AUTO_APPROVE_THRESHOLD) {
            reasons.push('amount \u20b9' + amountRequested + ' exceeds threshold \u20b9' + AUTO_APPROVE_THRESHOLD);
        }
        if (caseFraudFlagged) {
            reasons.push('case flagged for fraud review');
        }
        if (suspiciousAmount) {
            reasons.push('requested amount exceeds 3x order value');
        }
        decisionNotes = 'Auto-escalated: ' + reasons.join(', ') + '. Requires manual review.';
        amountApproved = 0;
    }

    // Create the refund request record WITH decision already set
    // Decision and fraud_flagged are NEVER from client input
    var refundGr = new GlideRecord('x_2145749_qc_refund_request');
    refundGr.initialize();
    refundGr.setValue('case', caseGr.getUniqueValue());
    refundGr.setValue('order_number', body.order_number || caseGr.getValue('x_2145749_qc_order_number') || '');
    refundGr.setValue('request_type', body.request_type);
    refundGr.setValue('amount_requested', amountRequested);
    refundGr.setValue('amount_approved', amountApproved);
    refundGr.setValue('decision', decision);
    refundGr.setValue('decision_notes', decisionNotes);
    refundGr.setValue('fraud_flagged', fraudFlagged);
    refundGr.setValue('customer', gs.getUserID());

    var refundSysId = refundGr.insert();

    if (!refundSysId) {
        response.setStatus(500);
        response.setBody({ success: false, error: 'Failed to create refund request record' });
        return;
    }

    // Retrieve the generated number
    var createdGr = new GlideRecord('x_2145749_qc_refund_request');
    createdGr.get(refundSysId);
    var refundNumber = createdGr.getValue('number') || '';

    // Build decision label for UI display
    var decisionLabels = {
        'auto_approved': 'Auto-Approved',
        'auto_escalated': 'Escalated for Review'
    };

    var message = '';
    if (decision === 'auto_approved') {
        message = 'Your refund of \u20b9' + amountRequested + ' has been automatically approved. Refund reference: ' + refundNumber;
    } else {
        message = 'Your refund request has been escalated for manual review. Reference: ' + refundNumber + '. A team member will review within 24 hours.';
    }

    response.setStatus(201);
    response.setBody({
        success: true,
        number: refundNumber,
        sys_id: refundSysId,
        decision: decision,
        decision_label: decisionLabels[decision] || decision,
        amount_approved: amountApproved,
        message: message
    });
})(request, response);
